import copy
import hashlib
import json

STATUS_ORDER = {"DRAFT": 0, "SUBMITTED": 1, "AUTHORISED": 2}
# The highest Xero status the agent may set, by the client's approval route. Any other route: Draft only.
MAX_STATUS = {"bookkeeper": "AUTHORISED", "hj_reviewer": "AUTHORISED", "client_each_bill": "SUBMITTED"}


class Refused(Exception):
    def __init__(self, code, reason):
        super().__init__(reason)
        self.code = code
        self.reason = reason


def as_data(value):
    if isinstance(value, str):
        try:
            return json.loads(value)
        except Exception:
            return value
    return value


def tidy(value):
    """The same value however it was written: 100 and 100.0 compare equal."""
    value = as_data(value)
    if isinstance(value, dict):
        return {str(k): tidy(v) for k, v in value.items()}
    if isinstance(value, list):
        return [tidy(v) for v in value]
    if isinstance(value, float) and value.is_integer():
        return int(value)
    return value


def approval_digest(action, tenant, invoice, invoice_id, patch):
    body = {"action": action, "xero_tenant_id": tenant}
    if action == "create":
        body["invoice"] = invoice
    else:
        body["invoice_id"] = invoice_id
        body["patch"] = patch
    text = json.dumps(tidy(body), sort_keys=True, separators=(",", ":"), ensure_ascii=False)
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:12]


def approval_from_params():
    action = str(params.get("action") or "").strip().lower()
    tenant = str(params.get("xero_tenant_id") or "").strip()
    invoice = tidy(params.get("invoice")) if action == "create" else None
    invoice_id = str(params.get("invoice_id") or "").strip() if action == "update" else ""
    patch = tidy(params.get("patch")) if action == "update" else None
    return action, tenant, invoice, invoice_id, patch


def first_invoice(value):
    value = as_data(value)
    if isinstance(value, dict):
        rows = value.get("Invoices") or value.get("invoices")
        if isinstance(rows, list):
            return rows[0] if rows and isinstance(rows[0], dict) else {}
        if value.get("InvoiceID"):
            return value
    if isinstance(value, list) and value and isinstance(value[0], dict):
        return value[0]
    return {}


def all_invoices(value):
    value = as_data(value)
    if isinstance(value, dict):
        rows = value.get("Invoices") or value.get("invoices") or []
        return [r for r in rows if isinstance(r, dict)]
    if isinstance(value, list):
        return [r for r in value if isinstance(r, dict)]
    return []


def amount(value):
    try:
        return round(float(value), 4)
    except Exception:
        return None


def get_record(type_slug, record_id):
    if not record_id:
        return {}
    row = as_data(api.records.get(type_slug=type_slug, record_id=record_id))
    if isinstance(row, dict) and isinstance(row.get("record"), dict):
        row = row["record"]
    return row if isinstance(row, dict) else {}


def field(row, key):
    data = row.get("data") or row.get("fields") or {}
    return data.get(key, row.get(key))


def client_id_of(row):
    links = row.get("links") if isinstance(row.get("links"), dict) else {}
    found = links.get("client") or field(row, "client")
    if isinstance(found, list):
        found = found[0] if found else ""
    if isinstance(found, dict):
        found = found.get("id") or found.get("record_id") or ""
    return str(found or "")


def bill_context(record_id, tenant):
    """The AP bill row, its client's approval route, and a check that the Xero organisation is that client's."""
    row = get_record("ap_bill", record_id)
    if not row:
        raise Refused("bad_input", "The AP bill row couldn't be read.")
    client = get_record("client", client_id_of(row))
    route = str(field(row, "approval_route") or field(client, "ap_approval_route") or "").strip().lower()
    given = str(params.get("route") or "").strip().lower()
    if given and given != route:
        raise Refused("route", f"The route given ({given}) isn't this client's route ({route or 'none'}).")
    row_tenant = str(field(row, "xero_tenant_id") or "").strip()
    client_tenant = str(field(client, "ap_xero_tenant_id") or "").strip()
    if (row_tenant and row_tenant != tenant) or (client_tenant and client_tenant != tenant):
        raise Refused("tenant", "That Xero organisation isn't the one this bill's client uses.")
    return row, route


def same_supplier(bill, contact):
    theirs = bill.get("Contact") or {}
    if contact.get("ContactID") and theirs.get("ContactID"):
        return contact.get("ContactID") == theirs.get("ContactID")
    mine = str(contact.get("Name") or "").strip().lower()
    return bool(mine) and mine == str(theirs.get("Name") or "").strip().lower()


def in_job():
    return str((trigger or {}).get("kind") or "") == "process"
def main():
    action, tenant, bill, bill_id, patch = approval_from_params()
    record_id = str(params.get("bill_record_id") or "").strip()
    if action not in ("create", "update") or not tenant or not record_id:
        raise Refused("bad_input", "The action, the Xero organisation ID and the AP bill row are all needed.")
    digest = approval_digest(action, tenant, bill, bill_id, patch)
    if str(params.get("sheet_digest") or "").strip() != digest:
        raise Refused("sheet_mismatch", "These values aren't the ones on the review sheet. Rebuild the sheet and ask again.")
    row, route = bill_context(record_id, tenant)
    if route != "hj_reviewer":
        raise Refused("route", "Only bills for clients on the internal review route go to internal review.")
    api.records.update(type_slug="ap_bill", record_id=record_id, record={"data": {"internal_review_digest": digest}})
    return digest


passed = False
